"""Local support widget; no external chat service or tracking script."""


def render_support_widget():
    return r'''<style>
.tr-chat-launcher{position:fixed;right:22px;bottom:22px;z-index:80;border:1px solid #b2dfcd66;border-radius:100px;background:#a8d8c4;color:#142920;padding:13px 19px;font:700 13px 'Segoe UI',Arial,sans-serif;box-shadow:0 8px 30px #0004;cursor:pointer}.tr-chat-box{position:fixed;right:22px;bottom:82px;width:360px;max-width:calc(100vw - 28px);height:480px;max-height:calc(100dvh - 110px);z-index:81;display:flex;flex-direction:column;background:#1c3038;border:1px solid #b2dfcd44;border-radius:20px;box-shadow:0 16px 70px #0008;overflow:hidden}.tr-chat-box[hidden],.tr-chat-compose[hidden],.tr-chat-signin[hidden]{display:none}.tr-chat-header{padding:16px 18px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff18}.tr-chat-header h2{font-size:16px;margin:0}.tr-chat-header button{background:none;border:0;color:#dcebe5;font-size:22px;cursor:pointer}.tr-chat-messages{padding:16px;overflow-y:auto;flex:1;min-height:0;display:flex;flex-direction:column;gap:10px}.tr-chat-bubble{background:#ffffff08;border-radius:12px;padding:10px 12px;font:13px/1.5 'Segoe UI',Arial,sans-serif;color:#dcebe5;white-space:pre-wrap;overflow-wrap:anywhere}.tr-chat-bubble.customer{background:#40645a80;margin-left:24px}.tr-chat-bubble.staff{margin-right:20px}.tr-chat-bubble small{display:block;font-size:10px;color:#a7c5bd;margin-bottom:4px}.tr-chat-compose{border-top:1px solid #ffffff18;padding:12px;display:flex;gap:8px}.tr-chat-compose textarea{width:100%;min-width:0;height:60px;padding:10px;resize:none;font-size:13px}.tr-chat-compose button{padding:8px 12px;font-size:12px}.tr-chat-notice{margin:0;padding:0 12px 10px;color:#bcd0ce;font-size:11px;line-height:1.4}.tr-chat-signin{padding:12px 16px;font-size:13px;line-height:1.5;border-top:1px solid #ffffff18}.tr-chat-signin a{color:#b9e4d1}@media(max-width:480px){.tr-chat-launcher{right:14px;bottom:14px}.tr-chat-box{right:14px;bottom:72px}}
</style><button class="tr-chat-launcher" id="tr-chat-open" type="button" aria-expanded="false" aria-controls="tr-chat-box">Live Chat</button><section class="tr-chat-box" id="tr-chat-box" aria-label="TableRadar live chat" hidden><header class="tr-chat-header"><h2>TableRadar support</h2><button type="button" id="tr-chat-close" aria-label="Close live chat">×</button></header><div class="tr-chat-messages" id="tr-chat-messages" role="log" aria-live="polite"><div class="tr-chat-bubble staff">Hi! Welcome to TableRadar. How can we help?</div></div><div class="tr-chat-signin" id="tr-chat-signin" hidden><a href="/signin_login">Sign in</a> or <a href="/signup">create an account</a> to message our team and keep your conversation.</div><form class="tr-chat-compose" id="tr-chat-compose" hidden><textarea name="message" maxlength="2000" aria-label="Your message" placeholder="Write a message…" required></textarea><button class="tr-button" type="submit">Send</button></form><p class="tr-chat-notice" id="tr-chat-notice">Our administrators and managers will reply here. Please do not send passwords or payment keys.</p></section>
<script>(function(){
const box=document.getElementById('tr-chat-box'),launch=document.getElementById('tr-chat-open'),messages=document.getElementById('tr-chat-messages'),form=document.getElementById('tr-chat-compose'),signin=document.getElementById('tr-chat-signin'),notice=document.getElementById('tr-chat-notice');let timer=null,csrf='',nonce='',signature='',busy=false;
function draw(items){let key=JSON.stringify(items);if(signature===key)return;signature=key;messages.replaceChildren();const welcome=document.createElement('div');welcome.className='tr-chat-bubble staff';welcome.textContent='Hi! Welcome to TableRadar. How can we help?';messages.append(welcome);items.forEach(m=>{const b=document.createElement('div');b.className='tr-chat-bubble '+(m.sender==='customer'?'customer':'staff');const label=document.createElement('small');label.textContent=m.sender==='customer'?'You':'TableRadar team';b.append(label,document.createTextNode(m.body));messages.append(b)});messages.scrollTop=messages.scrollHeight}
async function load(){try{const r=await fetch('/support/chat',{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw Error();const data=await r.json();csrf=data.csrf||'';signin.hidden=data.signed_in;form.hidden=!data.signed_in;draw(data.messages||[])}catch(e){notice.textContent='Chat is temporarily unavailable. Please try again shortly.'}}
function open(){box.hidden=false;launch.setAttribute('aria-expanded','true');load();clearInterval(timer);timer=setInterval(load,10000)}
launch.addEventListener('click',()=>box.hidden?open():close());function close(){box.hidden=true;launch.setAttribute('aria-expanded','false');clearInterval(timer);launch.focus()}document.getElementById('tr-chat-close').addEventListener('click',close);document.querySelectorAll('[data-open-live-chat]').forEach(b=>b.addEventListener('click',open));
form.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const input=form.querySelector('textarea'),text=input.value.trim();if(!text)return;busy=true;form.querySelector('button').disabled=true;nonce=nonce||crypto.randomUUID();try{const data=new URLSearchParams({body:text,csrf,nonce});const r=await fetch('/support/chat/message',{method:'POST',credentials:'same-origin',body:data});const result=await r.json();if(!r.ok)throw Error(result.error||'Message could not be sent. Please try again.');input.value='';nonce='';notice.textContent='Message sent. Our team will reply here.';await load()}catch(e){notice.textContent=e.message||'Message could not be sent.'}finally{busy=false;form.querySelector('button').disabled=false}});
})();</script>'''
